import React from 'react';
import { ChevronDown, Menu, MapPin } from 'lucide-react';

const CategoryBar = () => {
  const categories = [
    'Fresh',
    'Prime Video',
    'Sell',
    'Bestsellers',
    "Today's Deals",
    'Mobile',
    'New Releases',
    'Prime',
    'Amazon Pay',
    'Electronics',
    'Customer Service',
    'Home & Kitchen',
    'Fashion',
    'Computers',
    'Toys & Games'
  ];

  return (
    <div className="bg-amazon-light text-white">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex items-center h-10 space-x-3 overflow-x-auto scrollbar-hide">
          {/* All Menu */}
          <div className="flex items-center space-x-1 hover:border border-white/30 px-2 py-1 rounded cursor-pointer whitespace-nowrap">
            <Menu size={18} />
            <span className="text-sm font-medium">All</span>
          </div>

          {/* Location */}
          <div className="hidden lg:flex items-center space-x-1 hover:border border-white/30 px-2 py-1 rounded cursor-pointer whitespace-nowrap">
            <MapPin size={16} />
            <div className="text-xs">
              <span className="text-gray-300">Delivering to</span>
              <div className="font-bold text-sm -mt-0.5">Khordha 752056</div>
            </div>
          </div>

          {/* Categories */}
          {categories.map((category, index) => (
            <div
              key={index}
              className="hover:border border-white/30 px-2 py-1 rounded cursor-pointer whitespace-nowrap text-sm hover:text-white/90 transition-colors"
            >
              {category}
            </div>
          ))}

          {/* Trending arrow indicator */}
          <div className="flex items-center text-sm hover:border border-white/30 px-2 py-1 rounded cursor-pointer whitespace-nowrap">
            <span>Trending</span>
            <ChevronDown size={14} className="ml-1" />
          </div>
        </div>
      </div>
    </div>
  );
};

export default CategoryBar;
